(()=>{const data=window.HANZI_SITE_MESSAGES;const overrides={...data.hi};Object.assign(data.hi,{"Skip to content":"मुख्य सामग्री पर जाएँ","Previous screenshot":"पिछला स्क्रीनशॉट","Next screenshot":"अगला स्क्रीनशॉट","Hanzi Plus":"Hanzi Plus","ИНН: 695205887530":"कर पहचान संख्या: 695205887530","Тарифы и контакты":"प्लान और संपर्क","разделе 6":"अनुभाग 6 में","1 Общие положения":"1 सामान्य प्रावधान","Покаместова Анастасия Максимовна, ИНН 695205887530, физическое лицо, применяющее специальный налоговый режим «Налог на профессиональный доход» (далее — Исполнитель), предлагает пользователю (далее — Заказчик) заключить договор на следующих условиях.":"Anastasia Maksimovna Pokamestova, कर पहचान संख्या 695205887530, विशेष «पेशेवर आय कर» व्यवस्था अपनाने वाली व्यक्ति (सेवा प्रदाता), उपयोगकर्ता (ग्राहक) को निम्न शर्तों पर अनुबंध का प्रस्ताव देती हैं।","Raccoon App Labs — обозначение разработчика, а не отдельная сторона договора.":"Raccoon App Labs डेवलपर का नाम है, अनुबंध का अलग पक्ष नहीं।","До оплаты Заказчик знакомится с офертой, составом доступа, ценой, сроком и требованиями к приложению.":"भुगतान से पहले ग्राहक प्रस्ताव, उपलब्ध पहुँच, मूल्य, अवधि और ऐप की आवश्यकताएँ पढ़ता है।","Акцепт — успешная оплата выбранного тарифа после предоставления возможности ознакомиться с офертой.":"प्रस्ताव पढ़ने का अवसर मिलने के बाद चुने प्लान का सफल भुगतान उसकी स्वीकृति है।","Установка приложения, бесплатная регистрация или просмотр сайта сами по себе не являются акцептом и не создают обязанности платить.":"ऐप इंस्टॉल करना, मुफ़्त पंजीकरण या वेबसाइट देखना अपने-आप स्वीकृति या भुगतान की बाध्यता नहीं बनाते।","1.4. Договор заключается с дееспособным Заказчиком. При необходимости покупку от имени несовершеннолетнего совершает его законный представитель.":"1.4. अनुबंध कानूनी रूप से सक्षम ग्राहक से होता है। आवश्यकता होने पर नाबालिग की ओर से उसका कानूनी प्रतिनिधि खरीदता है।","2 Предмет договора":"2 अनुबंध का विषय","Неопубликованные уроки и уровни, отмеченные «скоро», не являются доступными материалами на дату покупки.":"«जल्द आ रहा है» वाले अप्रकाशित पाठ और स्तर खरीद की तारीख को उपलब्ध सामग्री नहीं हैं।","Если новые материалы публикуются в течение оплаченного срока, они доступны по действующему Plus без дополнительной платы.":"सशुल्क अवधि में नई सामग्री प्रकाशित होने पर वह सक्रिय Plus में बिना अतिरिक्त शुल्क मिलती है।","Услуга не включает индивидуальные занятия, консультации преподавателя, выдачу документа об образовании или гарантию сдачи экзамена HSK.":"इसमें व्यक्तिगत कक्षाएँ, शिक्षक परामर्श, शैक्षिक प्रमाणपत्र या HSK परीक्षा पास करने की गारंटी नहीं है।","Права на приложение и материалы не передаются Заказчику в собственность.":"ऐप और सामग्री का स्वामित्व ग्राहक को नहीं मिलता।","Допускается их личное использование в пределах функций приложения.":"ऐप की सुविधाओं के भीतर निजी उपयोग की अनुमति है।","3 Цена и оплата":"3 मूल्य और भुगतान","На условиях настоящей редакции применяется разовая оплата.":"इस संस्करण में भुगतान एकमुश्त है।","Автоматическое продление и повторные списания не предусмотрены.":"अपने-आप नवीनीकरण या दोबारा कटौती नहीं होती।","Продление выполняется новой покупкой по цене и условиям, показанным перед её оплатой.":"अवधि बढ़ाने के लिए उस समय दिखाई गई कीमत और शर्तों पर नई खरीद ज़रूरी है।","Исполнитель формирует и передаёт Заказчику чек плательщика НПД в порядке и сроки, установленные законодательством, самостоятельно через «Мой налог» либо через уполномоченный сервис.":"सेवा प्रदाता कानून द्वारा तय तरीके और समय में «Мой налог» या अधिकृत सेवा से पेशेवर आय कर की रसीद बनाकर ग्राहक को देती हैं।","Подтверждение оплаты платёжного сервиса не заменяет обязанность передать чек НПД.":"भुगतान सेवा की पुष्टि कर रसीद देने की बाध्यता का विकल्प नहीं है।","4 Активация и срок доступа":"4 सक्रियण और पहुँच अवधि","Plus активируется в аккаунте после серверного подтверждения платежа выбранным сервисом.":"चुनी सेवा के भुगतान की सर्वर पुष्टि के बाद खाते में Plus सक्रिय होता है।","Само создание заказа или возврат браузера со страницы оплаты доступ не активирует.":"ऑर्डर बनना या भुगतान पेज से लौटना अपने-आप पहुँच सक्रिय नहीं करता।","После покупки в приложении можно нажать «Проверить мой Plus».":"खरीद के बाद ऐप में «मेरा Plus जाँचें» दबा सकते हैं।","Предельный срок активации — 24 часа с момента подтверждения оплаты.":"भुगतान पुष्टि के बाद सक्रियण अधिकतम 24 घंटे में होता है।","При технической задержке Заказчик обращается в поддержку с номером заказа, датой оплаты и идентификатором аккаунта.":"तकनीकी देरी पर ऑर्डर संख्या, भुगतान की तारीख और खाता पहचान के साथ सहायता से संपर्क करें।","Оплаченный срок начинается с фактической активации доступа.":"सशुल्क अवधि वास्तविक सक्रियण से शुरू होती है।","Дата и время окончания отображаются в приложении.":"समाप्ति की तारीख और समय ऐप में दिखते हैं।","Календарный месяц заканчивается в соответствующее число следующего месяца; при отсутствии такого числа — в последний день соответствующего месяца.":"कैलेंडर महीना अगले महीने की उसी तारीख को समाप्त होता है; तारीख न हो तो उसके अंतिम दिन।","5 Права и обязанности сторон":"5 पक्षों के अधिकार और दायित्व","Исполнитель обеспечивает оплаченный доступ, устраняет относящиеся к услуге неисправности и рассматривает обращения по оплате и доступу.":"सेवा प्रदाता सशुल्क पहुँच देती हैं, संबंधित खराबियाँ ठीक करती हैं और भुगतान तथा पहुँच के अनुरोध देखती हैं।","Плановые технические работы по возможности проводятся с предварительным уведомлением.":"जहाँ संभव हो, नियोजित रखरखाव की पहले सूचना दी जाती है।","Технический сбой сам по себе не освобождает Исполнителя от обязательств.":"तकनीकी खराबी अपने-आप सेवा प्रदाता को दायित्वों से मुक्त नहीं करती।","Если по причинам на стороне Исполнителя оплаченный доступ существенно недоступен, Заказчик вправе потребовать устранения неисправности и воспользоваться предусмотренными законом средствами защиты.":"सेवा प्रदाता की ओर की वजह से सशुल्क पहुँच बहुत बाधित हो तो ग्राहक सुधार और कानूनी उपचार माँग सकता है।","Стороны могут согласовать продление срока на период недоступности без ограничения права на возврат.":"धनवापसी के अधिकार को सीमित किए बिना बंद रहने की अवधि जितना समय बढ़ाने पर सहमति हो सकती है।","Заказчик предоставляет сведения, необходимые для исполнения заказа и передачи чека, обеспечивает сохранность доступа к своему аккаунту и не передаёт подписку третьим лицам.":"ग्राहक ऑर्डर और रसीद के लिए आवश्यक जानकारी देता है, खाते की सुरक्षा रखता है और सदस्यता दूसरों को नहीं देता।","Запрещены незаконное распространение материалов и обход средств защиты приложения.":"सामग्री का गैरकानूनी वितरण और ऐप की सुरक्षा को दरकिनार करना निषिद्ध है।","Личное повторение уроков разрешено.":"व्यक्तिगत पाठ पुनरावृत्ति की अनुमति है।","6 Отказ от услуги и возврат":"6 सेवा से हटना और धनवापसी","Заказчик вправе отказаться от договора, направив уведомление на контактную почту Исполнителя.":"ग्राहक सेवा प्रदाता के ईमेल पर सूचना देकर अनुबंध छोड़ सकता है।","В обращении достаточно указать аккаунт, номер заказа или иные данные, позволяющие найти платёж, и дату оплаты.":"खाता, ऑर्डर संख्या या भुगतान खोजने की अन्य जानकारी और भुगतान तारीख पर्याप्त हैं।","Обоснование личных причин отказа не требуется.":"छोड़ने के निजी कारण समझाना आवश्यक नहीं।","При отказе Исполнитель возвращает оплату за вычетом только фактически понесённых расходов, непосредственно связанных с исполнением этого договора и подтверждённых документами, в пределах применимого законодательства.":"छोड़ने पर लागू कानून के भीतर केवल इस अनुबंध से सीधे जुड़े वास्तविक, दस्तावेज़ित खर्च काटकर भुगतान लौटाया जाता है।","Фиксированный штраф, безусловное удержание всей оплаты или автоматическое удержание комиссии сервиса не устанавливаются.":"तय जुर्माना, पूरा भुगतान बिना शर्त रोकना या सेवा शुल्क अपने-आप काटना निर्धारित नहीं है।","Расчёт и подтверждение удержаний предоставляются Заказчику.":"कटौतियों की गणना और प्रमाण ग्राहक को दिए जाते हैं।","При непредоставлении доступа, ненадлежащем качестве или нарушении срока активации применяются права и сроки, предусмотренные законодательством.":"पहुँच न मिले, गुणवत्ता खराब हो या सक्रियण में देरी हो तो कानूनी अधिकार और समयसीमाएँ लागू हैं।","Если доступ не предоставлен и Исполнитель не подтверждает законные основания удержаний, оплата возвращается полностью.":"पहुँच न मिली हो और कटौती का कानूनी आधार सिद्ध न हो तो पूरा भुगतान लौटता है।","Повторный ошибочный платёж возвращается без повторного предоставления услуги.":"गलती से दोहराया भुगतान सेवा दोबारा दिए बिना लौटाया जाता है।","Договорный срок возврата — не позднее 10 календарных дней с получения уведомления и сведений, достаточных для идентификации платежа, если законом не установлен более короткий срок.":"सूचना और भुगतान पहचानने की पर्याप्त जानकारी मिलने के अधिकतम 10 कैलेंडर दिनों में धनवापसी होती है, जब तक कानून इससे कम समय न माँगे।","Возврат производится через платёжный сервис по исходному платежу, когда это технически возможно.":"तकनीकी रूप से संभव हो तो मूल लेनदेन की भुगतान सेवा से धनवापसी होती है।","Время зачисления банком может отличаться от времени отправки возврата.":"बैंक में राशि आने का समय धनवापसी भेजने के समय से अलग हो सकता है।","Доступ Plus прекращается при прекращении договора.":"अनुबंध समाप्त होने पर Plus पहुँच समाप्त होती है।","Возврат и окончание доступа не служат основанием для удаления сохранённого прогресса.":"धनवापसी या पहुँच का अंत सहेजी प्रगति मिटाने का आधार नहीं।","Обращение в поддержку не ограничивает право Заказчика на предусмотренные законом способы защиты.":"सहायता से संपर्क ग्राहक के कानूनी उपचार सीमित नहीं करता।","7 Персональные данные":"7 व्यक्तिगत डेटा","Исполнитель обрабатывает данные аккаунта, сведения о заказе, оплате и обращениях в объёме, необходимом для заключения и исполнения договора, выполнения обязанностей по учёту доходов и защиты законных прав, на соответствующих правовых основаниях.":"सेवा प्रदाता खाता, ऑर्डर, भुगतान और सहायता डेटा को अनुबंध, आय लेखांकन और कानूनी अधिकारों की रक्षा के लिए आवश्यक सीमा में उचित कानूनी आधारों पर संसाधित करती हैं।","Сведения об обработке, сроках хранения, получателях и правах пользователя опубликованы в":"प्रसंस्करण, भंडारण, प्राप्तकर्ताओं और अधिकारों की जानकारी","политике конфиденциальности":"गोपनीयता नीति में है",". Ознакомление с ней доступно до запроса кода и до покупки.":"। कोड माँगने और खरीद से पहले इसे पढ़ सकते हैं।","Оплата не означает согласия на рекламные рассылки.":"भुगतान विज्ञापन ईमेल की सहमति नहीं है।","Для обработки, требующей отдельного согласия, оно запрашивается отдельно.":"जहाँ अलग सहमति चाहिए, वह अलग माँगी जाती है।","Исполнитель не получает полный номер банковской карты и код её проверки от Заказчика.":"सेवा प्रदाता को ग्राहक का पूरा कार्ड नंबर या सत्यापन कोड नहीं मिलता।","8 Ответственность и разрешение споров":"8 दायित्व और विवाद समाधान","Стороны отвечают за нарушение обязательств в соответствии с применимым законодательством.":"दायित्व उल्लंघन के लिए पक्ष लागू कानून के अनुसार उत्तरदायी हैं।","Оферта не исключает и не ограничивает обязательные права Заказчика.":"यह प्रस्ताव ग्राहक के अनिवार्य अधिकार सीमित या समाप्त नहीं करता।","Привлечение платёжного или технического подрядчика не освобождает Исполнителя от его обязанностей по предоставлению услуги.":"भुगतान या तकनीकी ठेकेदार रखने से सेवा प्रदाता के सेवा दायित्व समाप्त नहीं होते।","Чрезвычайные и непредотвратимые обстоятельства учитываются в порядке, предусмотренном законом.":"असाधारण और अपरिहार्य परिस्थितियाँ कानून के अनुसार देखी जाती हैं।","Обычные технические неисправности не признаются такими обстоятельствами автоматически.":"साधारण तकनीकी खराबी अपने-आप ऐसी परिस्थिति नहीं मानी जाती।","При невозможности продолжения доступа стороны решают вопрос о прекращении договора и возврате за непредоставленную услугу.":"पहुँच जारी रखना असंभव हो तो अनुबंध समाप्ति और न दी गई सेवा की धनवापसी तय की जाती है।","Заказчик может направить обращение на контактную почту Исполнителя.":"ग्राहक सेवा प्रदाता के ईमेल पर अनुरोध भेज सकता है।","Обращение в поддержку не является обязательным условием судебной защиты, если обязательный порядок не установлен законом.":"कानून अनिवार्य न करे तो अदालत जाने से पहले सहायता से संपर्क ज़रूरी नहीं।","Подсудность определяется законодательством с сохранением права потребителя на выбор суда в предусмотренных законом случаях.":"कानून के अनुसार क्षेत्राधिकार तय होगा और जहाँ लागू हो उपभोक्ता का अदालत चुनने का अधिकार सुरक्षित रहेगा।","9 Действие и изменение оферты":"9 प्रस्ताव की अवधि और बदलाव","9.1. Оферта применяется с даты публикации при открытом приёме оплаты и действует до её отзыва. Договор действует с акцепта до полного исполнения обязательств.":"9.1. भुगतान खुले होने पर प्रस्ताव प्रकाशन से वापस लेने तक लागू है। अनुबंध स्वीकृति से सभी दायित्व पूरे होने तक रहता है।","Новые цены и редакции применяются к новым покупкам после их публикации.":"नए मूल्य और संस्करण प्रकाशन के बाद की नई खरीद पर लागू हैं।","Изменение страницы или оферты не изменяет цену, срок и объём уже оплаченного доступа.":"पेज या प्रस्ताव बदलने से पहले से भुगतान की गई पहुँच का मूल्य, अवधि या दायरा नहीं बदलता।","Для подтверждения условий заказа Исполнитель сохраняет сведения о тарифе и применённой редакции оферты.":"ऑर्डर की शर्तें सिद्ध करने के लिए प्लान और लागू प्रस्ताव संस्करण रखा जाता है।","10 Реквизиты исполнителя":"10 सेवा प्रदाता का विवरण","ФИО: Покаместова Анастасия Максимовна":"पूरा नाम: Anastasia Maksimovna Pokamestova","Статус: физическое лицо, плательщик НПД":"स्थिति: व्यक्ति, पेशेवर आय करदाता","Город: Тверь":"शहर: Tver","Юридически значимые обращения направляются на электронную почту Исполнителя, указанную ниже":"कानूनी रूप से महत्वपूर्ण अनुरोध नीचे दिए सेवा प्रदाता के ईमेल पर भेजें","Телефон: +7 903 033-23-19":"फ़ोन: +7 903 033-23-19","Электронная почта: raccoon.app.labs@gmail.com":"ईमेल: raccoon.app.labs@gmail.com","Сайт: https://raccoon-app-labs.github.io/apps/hanzi-bloom/plus/":"वेबसाइट: https://raccoon-app-labs.github.io/apps/hanzi-bloom/plus/","Связаться с исполнителем":"सेवा प्रदाता से संपर्क करें","Публичная оферта Hanzi Plus":"Hanzi Plus का सार्वजनिक प्रस्ताव","Архив первой редакции от 16 октября 2026 года.":"16 अक्टूबर 2026 के प्रथम संस्करण का संग्रह।","Действующая редакция":"वर्तमान संस्करण","О предоставлении платного доступа к функциям и учебным материалам приложений Hanzi Bloom и Hanzi Keys":"Hanzi Bloom और Hanzi Keys की सुविधाओं और शिक्षण सामग्री की सशुल्क पहुँच के लिए","Два приложения. Одна подписка.":"दो ऐप। एक सदस्यता।","Hanzi Bloom + Hanzi Keys: 299 ₽ за календарный месяц или 2 999 ₽ за 12 календарных месяцев.":"Hanzi Bloom + Hanzi Keys: 299 ₽ में एक कैलेंडर महीना या 2 999 ₽ में 12 कैलेंडर महीने।","Разовая оплата через Робокассу, без автопродления.":"Robokassa से एक बार भुगतान, अपने-आप नवीनीकरण नहीं।","Об отказе от услуги и возврате — в":"सेवा छोड़ने और धनवापसी के बारे में","Редакция от 16 октября 2026 года. Версия условий: 2026-10-16. Место составления: Тверь.":"16 अक्टूबर 2026 का संस्करण। शर्त संस्करण: 2026-10-16। जारी स्थान: Tver।","Сайт услуги и тарифов: https://raccoon-app-labs.github.io/apps/hanzi-bloom/plus/.":"सेवा और प्लान: https://raccoon-app-labs.github.io/apps/hanzi-bloom/plus/.","Hanzi Plus — единый платный доступ для личного использования в двух Android-приложениях: Hanzi Bloom (com.enotessa.hanzi) и Hanzi Keys (com.enotessa.chinesekeys).":"Hanzi Plus दो Android ऐप, Hanzi Bloom (com.enotessa.hanzi) और Hanzi Keys (com.enotessa.chinesekeys), की साझा सशुल्क निजी पहुँच है।","Настоящая редакция регулирует покупки российской версии через Робокассу в рублях.":"यह संस्करण Robokassa से रूबल में रूसी ऐप की खरीद पर लागू है।","Международные продажи через Lava и другие сервисы сейчас не предлагаются.":"Lava या अन्य सेवाओं से अंतरराष्ट्रीय बिक्री अभी उपलब्ध नहीं।","Условия ранее оплаченных заказов сохраняются по редакции, принятой при их оплате.":"पुराने भुगतान किए ऑर्डर पर भुगतान के समय स्वीकृत शर्तें रहती हैं।","На оплаченный срок один аккаунт получает доступ в обоих приложениях: в Hanzi Bloom — к опубликованным урокам курса HSK 1–3 без просмотра рекламы для открытия урока; в Hanzi Keys — к защищённым подпиской занятиям, практике, учебному маршруту и разбору ключей, с отключением рекламы.":"सशुल्क अवधि में खाते को Bloom में प्रकाशित HSK 1–3 पाठ विज्ञापन के बिना और Keys में संरक्षित गतिविधियाँ, अभ्यास, सीखने का मार्ग और मूल घटक विश्लेषण बिना विज्ञापन मिलते हैं।","Для доступа в каждом приложении нужно войти с одной и той же почтой в российский аккаунт Hanzi.":"दोनों ऐप में उसी ईमेल से रूसी Hanzi खाते में प्रवेश करें।","Отдельно платить за второе приложение не требуется.":"दूसरे ऐप के लिए अलग भुगतान नहीं चाहिए।","Состав опубликованных упражнений зависит от установленной версии.":"प्रकाशित अभ्यासों का चयन इंस्टॉल किए संस्करण पर निर्भर है।","HSK 4–6, отмеченные «скоро», не предлагаются как уже опубликованные материалы.":"«जल्द आ रहा है» वाले HSK 4–6 पहले से प्रकाशित सामग्री के रूप में उपलब्ध नहीं।","Тарифы общего Hanzi Plus для России: 299 рублей за один календарный месяц либо 2 999 рублей за 12 календарных месяцев.":"रूस के साझा Hanzi Plus प्लान: 299 रूबल में एक कैलेंडर महीना या 2 999 रूबल में 12 कैलेंडर महीने।","Каждый тариф включает оба приложения на один общий срок, а не отдельную оплату за каждое.":"हर प्लान में दोनों ऐप एक साझा अवधि के लिए हैं; प्रत्येक की अलग कीमत नहीं।","Окончательные сумма, валюта, срок и состав доступа показываются до оплаты.":"भुगतान से पहले अंतिम राशि, मुद्रा, अवधि और पहुँच का दायरा दिखता है।","Цена включает стоимость услуги Исполнителя.":"मूल्य में सेवा प्रदाता की सेवा शामिल है।","Международные тарифы в этой редакции к оплате не предлагаются.":"इस संस्करण में अंतरराष्ट्रीय प्लान भुगतान के लिए उपलब्ध नहीं।","Оплата производится безналично на защищённой платёжной странице Робокассы.":"Robokassa के सुरक्षित पेज पर गैर-नकद भुगतान होता है।","В текущем выпуске оформление заказа доступно из российской версии приложения в RuStore.":"इस रिलीज़ में RuStore के रूसी ऐप से ऑर्डर बनता है।","Данные карты и банковские коды вводятся у платёжного сервиса; Исполнитель не запрашивает их в переписке.":"कार्ड और बैंक कोड भुगतान सेवा में डालें; सेवा प्रदाता संदेशों में नहीं माँगतीं।","Конвертация и возможные расходы банка при использовании иной валюты карты определяются банком и платёжным сервисом; эти условия проверяются до подтверждения платежа.":"कार्ड की अलग मुद्रा पर रूपांतरण और बैंक खर्च बैंक तथा भुगतान सेवा तय करते हैं; पुष्टि से पहले जाँचें।","До покупки Заказчик устанавливает актуальную версию хотя бы одного приложения с экраном аккаунта Hanzi Plus и входит по подтверждённой почте.":"खरीद से पहले कम-से-कम एक ऐप का वर्तमान Hanzi Plus खाता वाला संस्करण इंस्टॉल करके सत्यापित ईमेल से प्रवेश करें।","Для второго приложения используется тот же российский аккаунт: покупка связана с аккаунтом, а не с конкретной установкой или магазинным профилем.":"दूसरे ऐप में वही रूसी खाता उपयोग होता है; खरीद खाते से जुड़ी है, खास इंस्टॉल या स्टोर प्रोफ़ाइल से नहीं।","Оба приложения устанавливаются отдельно.":"दोनों ऐप अलग इंस्टॉल होते हैं।","Для оплаты, первой активации, восстановления и синхронизации нужно подключение к Интернету.":"भुगतान, पहली सक्रियता, बहाली और सिंक के लिए इंटरनेट चाहिए।","Системные требования указываются в карточках приложений.":"सिस्टम आवश्यकताएँ ऐप की स्टोर सूची में हैं।","Язык интерфейса сам по себе не меняет страну покупки или регион хранения аккаунта.":"इंटरफ़ेस की भाषा अपने-आप खरीद का देश या खाता भंडारण क्षेत्र नहीं बदलती।","При продлении действующего Plus новый оплаченный срок добавляется после окончания текущего; после истечения — начинается с новой активации.":"सक्रिय Plus बढ़ाने पर नई अवधि वर्तमान के बाद जुड़ती है; समाप्त हो चुका हो तो नए सक्रियण से।","Один срок применяется к обоим приложениям.":"एक ही अवधि दोनों ऐप पर लागू होती है।","Восстановление в том же аккаунте после переустановки или на другом устройстве не требует повторной оплаты и не начинает новый оплаченный срок.":"उसी खाते में दोबारा इंस्टॉल या दूसरे उपकरण पर बहाली का नया भुगतान या नई अवधि नहीं होती।","Ранее купленный российский Plus также распознаётся обоими приложениями на оставшийся срок без доплаты; ранее согласованные цена и срок не ухудшаются.":"पुराना रूसी Plus भी शेष अवधि के लिए दोनों ऐप में बिना अतिरिक्त शुल्क मान्य है; तय कीमत और अवधि खराब नहीं होतीं।","После окончания оплаченного срока платные возможности закрываются по правилам соответствующего приложения, но окончание подписки само по себе не удаляет учебный прогресс.":"समाप्ति के बाद हर ऐप के नियमों से सशुल्क सुविधाएँ बंद होती हैं, लेकिन इससे अध्ययन प्रगति नहीं मिटती।","Для аккаунтов, хотя бы раз получивших производственную подписку Plus, облачное хранение поддерживаемого прогресса остаётся доступным без продления.":"कम-से-कम एक बार उत्पादन Plus सदस्यता पाने वाले खातों में समर्थित क्लाउड प्रगति बिना नवीनीकरण रहती है।","В Hanzi Keys на сервер сохраняются только ID изученных ключей; снятие отметки «изучено» удаляет ID из списка.":"Keys केवल सीखे मूल घटकों की ID सर्वर पर रखता है; «सीखा» हटाने पर ID हटती है।","В Hanzi Bloom сохраняются поддерживаемые статусы слов и иероглифов, завершённые уроки, достигнутый уровень и результаты проверок глав.":"Bloom समर्थित शब्द और अक्षर स्थितियाँ, पूरे पाठ, स्तर और अध्याय जाँच परिणाम रखता है।","Это не полная копия всех настроек, расписаний повторений и локальных файлов.":"यह सभी सेटिंग, पुनरावृत्ति समयसारिणी और स्थानीय फ़ाइलों की पूरी प्रति नहीं।","Для отправки и восстановления нужны поддерживающая синхронизацию версия, Интернет и вход в тот же аккаунт; неотправленные локальные изменения после удаления приложения могут быть потеряны.":"भेजने और बहाल करने के लिए समर्थित संस्करण, इंटरनेट और वही खाता चाहिए; न भेजे स्थानीय बदलाव ऐप हटाने पर खो सकते हैं।","Удаление аккаунта по запросу прекращает облачное восстановление.":"अनुरोध पर खाता मिटने से क्लाउड बहाली समाप्त होती है।","4.6 Бесплатное знакомство в Hanzi Keys":"4.6 Hanzi Keys का मुफ़्त परिचय","В поддерживающей эту модель версии Keys предоставляется 7 суток знакомства с рекламой с момента подтверждённого сервером запуска.":"समर्थित Keys संस्करण में सर्वर द्वारा पुष्ट शुरुआत से विज्ञापन सहित 7 दिन का परिचय मिलता है।","По окончании защищённые занятия требуют Plus.":"उसके बाद संरक्षित गतिविधियों के लिए Plus चाहिए।","Бесплатный период сам не оформляет платную подписку и не вызывает списаний.":"मुफ़्त अवधि अपने-आप सशुल्क सदस्यता या कटौती नहीं बनाती।","Подробности доступны перед началом в приложении.":"शुरू करने से पहले ऐप में विवरण उपलब्ध हैं।","Предыдущая редакция:":"पिछला संस्करण:","8 октября 2026 года":"8 अक्टूबर 2026","Подписка Hanzi Plus":"Hanzi Plus सदस्यता","Explore app":"ऐप देखें","Translation for convenience. Original document: {language}.":"सुविधा के लिए अनुवाद। मूल दस्तावेज़ की भाषा: {language}।","Show original document":"मूल दस्तावेज़ दिखाएँ","Language":"भाषा","Choose your language":"अपनी भाषा चुनें","Search languages":"भाषाएँ खोजें","Close language selection":"भाषा सूची बंद करें","Language changed to {language}":"भाषा {language} कर दी गई","The page language does not change your payment region or currency.":"पेज की भाषा भुगतान क्षेत्र या मुद्रा नहीं बदलती।","No languages found":"कोई भाषा नहीं मिली","Use device language":"उपकरण की भाषा उपयोग करें","PERFECT KICK":"शानदार छलाँग!","{v0} · {v1}":"{v0} · {v1}","{v0} — {v1}. Found!":"{v0} — {v1}. मिल गया!","{v0} — {v1}. Ключ найден!":"{v0} — {v1}. मिल गया!","{v0} · {v1} servings":"{v0} · {v1} सर्विंग","{v0} · {v1} порц.":"{v0} · {v1} सर्विंग","{v0} — {v1} pcs":"{v0} — {v1} नग","{v0} — {v1} шт.":"{v0} — {v1} नग","{v0} — {v1} g":"{v0} — {v1} g","{v0} — {v1} г":"{v0} — {v1} g","Новый код · {seconds} с":"नया कोड · {seconds} सेकंड","· {v0} servings":"· {v0} सर्विंग","· {v0} порц.":"· {v0} सर्विंग","{remaining} left · {done} done":"{remaining} बाकी · {done} पूरे","Finish · {count} bought":"समाप्त करें · {count} खरीदे","{remaining} осталось · {done} готово":"{remaining} बाकी · {done} पूरे","Куплено: {count} · завершить":"समाप्त करें · {count} खरीदे"},overrides);Object.assign(window.HANZI_SOURCE_ALIASES||{},{"मुख्य सामग्री पर जाएँ":"Skip to content","पिछला स्क्रीनशॉट":"Previous screenshot","अगला स्क्रीनशॉट":"Next screenshot","कर पहचान संख्या: 695205887530":"ИНН: 695205887530","प्लान और संपर्क":"Тарифы и контакты","अनुभाग 6 में":"разделе 6","1 सामान्य प्रावधान":"1 Общие положения","Anastasia Maksimovna Pokamestova, कर पहचान संख्या 695205887530, विशेष «पेशेवर आय कर» व्यवस्था अपनाने वाली व्यक्ति (सेवा प्रदाता), उपयोगकर्ता (ग्राहक) को निम्न शर्तों पर अनुबंध का प्रस्ताव देती हैं।":"Покаместова Анастасия Максимовна, ИНН 695205887530, физическое лицо, применяющее специальный налоговый режим «Налог на профессиональный доход» (далее — Исполнитель), предлагает пользователю (далее — Заказчик) заключить договор на следующих условиях.","Raccoon App Labs डेवलपर का नाम है, अनुबंध का अलग पक्ष नहीं।":"Raccoon App Labs — обозначение разработчика, а не отдельная сторона договора.","भुगतान से पहले ग्राहक प्रस्ताव, उपलब्ध पहुँच, मूल्य, अवधि और ऐप की आवश्यकताएँ पढ़ता है।":"До оплаты Заказчик знакомится с офертой, составом доступа, ценой, сроком и требованиями к приложению.","प्रस्ताव पढ़ने का अवसर मिलने के बाद चुने प्लान का सफल भुगतान उसकी स्वीकृति है।":"Акцепт — успешная оплата выбранного тарифа после предоставления возможности ознакомиться с офертой.","ऐप इंस्टॉल करना, मुफ़्त पंजीकरण या वेबसाइट देखना अपने-आप स्वीकृति या भुगतान की बाध्यता नहीं बनाते।":"Установка приложения, бесплатная регистрация или просмотр сайта сами по себе не являются акцептом и не создают обязанности платить.","1.4. अनुबंध कानूनी रूप से सक्षम ग्राहक से होता है। आवश्यकता होने पर नाबालिग की ओर से उसका कानूनी प्रतिनिधि खरीदता है।":"1.4. Договор заключается с дееспособным Заказчиком. При необходимости покупку от имени несовершеннолетнего совершает его законный представитель.","2 अनुबंध का विषय":"2 Предмет договора","«जल्द आ रहा है» वाले अप्रकाशित पाठ और स्तर खरीद की तारीख को उपलब्ध सामग्री नहीं हैं।":"Неопубликованные уроки и уровни, отмеченные «скоро», не являются доступными материалами на дату покупки.","सशुल्क अवधि में नई सामग्री प्रकाशित होने पर वह सक्रिय Plus में बिना अतिरिक्त शुल्क मिलती है।":"Если новые материалы публикуются в течение оплаченного срока, они доступны по действующему Plus без дополнительной платы.","इसमें व्यक्तिगत कक्षाएँ, शिक्षक परामर्श, शैक्षिक प्रमाणपत्र या HSK परीक्षा पास करने की गारंटी नहीं है।":"Услуга не включает индивидуальные занятия, консультации преподавателя, выдачу документа об образовании или гарантию сдачи экзамена HSK.","ऐप और सामग्री का स्वामित्व ग्राहक को नहीं मिलता।":"Права на приложение и материалы не передаются Заказчику в собственность.","ऐप की सुविधाओं के भीतर निजी उपयोग की अनुमति है।":"Допускается их личное использование в пределах функций приложения.","3 मूल्य और भुगतान":"3 Цена и оплата","इस संस्करण में भुगतान एकमुश्त है।":"На условиях настоящей редакции применяется разовая оплата.","अपने-आप नवीनीकरण या दोबारा कटौती नहीं होती।":"Автоматическое продление и повторные списания не предусмотрены.","अवधि बढ़ाने के लिए उस समय दिखाई गई कीमत और शर्तों पर नई खरीद ज़रूरी है।":"Продление выполняется новой покупкой по цене и условиям, показанным перед её оплатой.","सेवा प्रदाता कानून द्वारा तय तरीके और समय में «Мой налог» या अधिकृत सेवा से पेशेवर आय कर की रसीद बनाकर ग्राहक को देती हैं।":"Исполнитель формирует и передаёт Заказчику чек плательщика НПД в порядке и сроки, установленные законодательством, самостоятельно через «Мой налог» либо через уполномоченный сервис.","भुगतान सेवा की पुष्टि कर रसीद देने की बाध्यता का विकल्प नहीं है।":"Подтверждение оплаты платёжного сервиса не заменяет обязанность передать чек НПД.","4 सक्रियण और पहुँच अवधि":"4 Активация и срок доступа","चुनी सेवा के भुगतान की सर्वर पुष्टि के बाद खाते में Plus सक्रिय होता है।":"Plus активируется в аккаунте после серверного подтверждения платежа выбранным сервисом.","ऑर्डर बनना या भुगतान पेज से लौटना अपने-आप पहुँच सक्रिय नहीं करता।":"Само создание заказа или возврат браузера со страницы оплаты доступ не активирует.","खरीद के बाद ऐप में «मेरा Plus जाँचें» दबा सकते हैं।":"После покупки в приложении можно нажать «Проверить мой Plus».","भुगतान पुष्टि के बाद सक्रियण अधिकतम 24 घंटे में होता है।":"Предельный срок активации — 24 часа с момента подтверждения оплаты.","तकनीकी देरी पर ऑर्डर संख्या, भुगतान की तारीख और खाता पहचान के साथ सहायता से संपर्क करें।":"При технической задержке Заказчик обращается в поддержку с номером заказа, датой оплаты и идентификатором аккаунта.","सशुल्क अवधि वास्तविक सक्रियण से शुरू होती है।":"Оплаченный срок начинается с фактической активации доступа.","समाप्ति की तारीख और समय ऐप में दिखते हैं।":"Дата и время окончания отображаются в приложении.","कैलेंडर महीना अगले महीने की उसी तारीख को समाप्त होता है; तारीख न हो तो उसके अंतिम दिन।":"Календарный месяц заканчивается в соответствующее число следующего месяца; при отсутствии такого числа — в последний день соответствующего месяца.","5 पक्षों के अधिकार और दायित्व":"5 Права и обязанности сторон","सेवा प्रदाता सशुल्क पहुँच देती हैं, संबंधित खराबियाँ ठीक करती हैं और भुगतान तथा पहुँच के अनुरोध देखती हैं।":"Исполнитель обеспечивает оплаченный доступ, устраняет относящиеся к услуге неисправности и рассматривает обращения по оплате и доступу.","जहाँ संभव हो, नियोजित रखरखाव की पहले सूचना दी जाती है।":"Плановые технические работы по возможности проводятся с предварительным уведомлением.","तकनीकी खराबी अपने-आप सेवा प्रदाता को दायित्वों से मुक्त नहीं करती।":"Технический сбой сам по себе не освобождает Исполнителя от обязательств.","सेवा प्रदाता की ओर की वजह से सशुल्क पहुँच बहुत बाधित हो तो ग्राहक सुधार और कानूनी उपचार माँग सकता है।":"Если по причинам на стороне Исполнителя оплаченный доступ существенно недоступен, Заказчик вправе потребовать устранения неисправности и воспользоваться предусмотренными законом средствами защиты.","धनवापसी के अधिकार को सीमित किए बिना बंद रहने की अवधि जितना समय बढ़ाने पर सहमति हो सकती है।":"Стороны могут согласовать продление срока на период недоступности без ограничения права на возврат.","ग्राहक ऑर्डर और रसीद के लिए आवश्यक जानकारी देता है, खाते की सुरक्षा रखता है और सदस्यता दूसरों को नहीं देता।":"Заказчик предоставляет сведения, необходимые для исполнения заказа и передачи чека, обеспечивает сохранность доступа к своему аккаунту и не передаёт подписку третьим лицам.","सामग्री का गैरकानूनी वितरण और ऐप की सुरक्षा को दरकिनार करना निषिद्ध है।":"Запрещены незаконное распространение материалов и обход средств защиты приложения.","व्यक्तिगत पाठ पुनरावृत्ति की अनुमति है।":"Личное повторение уроков разрешено.","6 सेवा से हटना और धनवापसी":"6 Отказ от услуги и возврат","ग्राहक सेवा प्रदाता के ईमेल पर सूचना देकर अनुबंध छोड़ सकता है।":"Заказчик вправе отказаться от договора, направив уведомление на контактную почту Исполнителя.","खाता, ऑर्डर संख्या या भुगतान खोजने की अन्य जानकारी और भुगतान तारीख पर्याप्त हैं।":"В обращении достаточно указать аккаунт, номер заказа или иные данные, позволяющие найти платёж, и дату оплаты.","छोड़ने के निजी कारण समझाना आवश्यक नहीं।":"Обоснование личных причин отказа не требуется.","छोड़ने पर लागू कानून के भीतर केवल इस अनुबंध से सीधे जुड़े वास्तविक, दस्तावेज़ित खर्च काटकर भुगतान लौटाया जाता है।":"При отказе Исполнитель возвращает оплату за вычетом только фактически понесённых расходов, непосредственно связанных с исполнением этого договора и подтверждённых документами, в пределах применимого законодательства.","तय जुर्माना, पूरा भुगतान बिना शर्त रोकना या सेवा शुल्क अपने-आप काटना निर्धारित नहीं है।":"Фиксированный штраф, безусловное удержание всей оплаты или автоматическое удержание комиссии сервиса не устанавливаются.","कटौतियों की गणना और प्रमाण ग्राहक को दिए जाते हैं।":"Расчёт и подтверждение удержаний предоставляются Заказчику.","पहुँच न मिले, गुणवत्ता खराब हो या सक्रियण में देरी हो तो कानूनी अधिकार और समयसीमाएँ लागू हैं।":"При непредоставлении доступа, ненадлежащем качестве или нарушении срока активации применяются права и сроки, предусмотренные законодательством.","पहुँच न मिली हो और कटौती का कानूनी आधार सिद्ध न हो तो पूरा भुगतान लौटता है।":"Если доступ не предоставлен и Исполнитель не подтверждает законные основания удержаний, оплата возвращается полностью.","गलती से दोहराया भुगतान सेवा दोबारा दिए बिना लौटाया जाता है।":"Повторный ошибочный платёж возвращается без повторного предоставления услуги.","सूचना और भुगतान पहचानने की पर्याप्त जानकारी मिलने के अधिकतम 10 कैलेंडर दिनों में धनवापसी होती है, जब तक कानून इससे कम समय न माँगे।":"Договорный срок возврата — не позднее 10 календарных дней с получения уведомления и сведений, достаточных для идентификации платежа, если законом не установлен более короткий срок.","तकनीकी रूप से संभव हो तो मूल लेनदेन की भुगतान सेवा से धनवापसी होती है।":"Возврат производится через платёжный сервис по исходному платежу, когда это технически возможно.","बैंक में राशि आने का समय धनवापसी भेजने के समय से अलग हो सकता है।":"Время зачисления банком может отличаться от времени отправки возврата.","अनुबंध समाप्त होने पर Plus पहुँच समाप्त होती है।":"Доступ Plus прекращается при прекращении договора.","धनवापसी या पहुँच का अंत सहेजी प्रगति मिटाने का आधार नहीं।":"Возврат и окончание доступа не служат основанием для удаления сохранённого прогресса.","सहायता से संपर्क ग्राहक के कानूनी उपचार सीमित नहीं करता।":"Обращение в поддержку не ограничивает право Заказчика на предусмотренные законом способы защиты.","7 व्यक्तिगत डेटा":"7 Персональные данные","सेवा प्रदाता खाता, ऑर्डर, भुगतान और सहायता डेटा को अनुबंध, आय लेखांकन और कानूनी अधिकारों की रक्षा के लिए आवश्यक सीमा में उचित कानूनी आधारों पर संसाधित करती हैं।":"Исполнитель обрабатывает данные аккаунта, сведения о заказе, оплате и обращениях в объёме, необходимом для заключения и исполнения договора, выполнения обязанностей по учёту доходов и защиты законных прав, на соответствующих правовых основаниях.","प्रसंस्करण, भंडारण, प्राप्तकर्ताओं और अधिकारों की जानकारी":"Сведения об обработке, сроках хранения, получателях и правах пользователя опубликованы в","गोपनीयता नीति में है":"политике конфиденциальности","। कोड माँगने और खरीद से पहले इसे पढ़ सकते हैं।":". Ознакомление с ней доступно до запроса кода и до покупки.","भुगतान विज्ञापन ईमेल की सहमति नहीं है।":"Оплата не означает согласия на рекламные рассылки.","जहाँ अलग सहमति चाहिए, वह अलग माँगी जाती है।":"Для обработки, требующей отдельного согласия, оно запрашивается отдельно.","सेवा प्रदाता को ग्राहक का पूरा कार्ड नंबर या सत्यापन कोड नहीं मिलता।":"Исполнитель не получает полный номер банковской карты и код её проверки от Заказчика.","8 दायित्व और विवाद समाधान":"8 Ответственность и разрешение споров","दायित्व उल्लंघन के लिए पक्ष लागू कानून के अनुसार उत्तरदायी हैं।":"Стороны отвечают за нарушение обязательств в соответствии с применимым законодательством.","यह प्रस्ताव ग्राहक के अनिवार्य अधिकार सीमित या समाप्त नहीं करता।":"Оферта не исключает и не ограничивает обязательные права Заказчика.","भुगतान या तकनीकी ठेकेदार रखने से सेवा प्रदाता के सेवा दायित्व समाप्त नहीं होते।":"Привлечение платёжного или технического подрядчика не освобождает Исполнителя от его обязанностей по предоставлению услуги.","असाधारण और अपरिहार्य परिस्थितियाँ कानून के अनुसार देखी जाती हैं।":"Чрезвычайные и непредотвратимые обстоятельства учитываются в порядке, предусмотренном законом.","साधारण तकनीकी खराबी अपने-आप ऐसी परिस्थिति नहीं मानी जाती।":"Обычные технические неисправности не признаются такими обстоятельствами автоматически.","पहुँच जारी रखना असंभव हो तो अनुबंध समाप्ति और न दी गई सेवा की धनवापसी तय की जाती है।":"При невозможности продолжения доступа стороны решают вопрос о прекращении договора и возврате за непредоставленную услугу.","ग्राहक सेवा प्रदाता के ईमेल पर अनुरोध भेज सकता है।":"Заказчик может направить обращение на контактную почту Исполнителя.","कानून अनिवार्य न करे तो अदालत जाने से पहले सहायता से संपर्क ज़रूरी नहीं।":"Обращение в поддержку не является обязательным условием судебной защиты, если обязательный порядок не установлен законом.","कानून के अनुसार क्षेत्राधिकार तय होगा और जहाँ लागू हो उपभोक्ता का अदालत चुनने का अधिकार सुरक्षित रहेगा।":"Подсудность определяется законодательством с сохранением права потребителя на выбор суда в предусмотренных законом случаях.","9 प्रस्ताव की अवधि और बदलाव":"9 Действие и изменение оферты","9.1. भुगतान खुले होने पर प्रस्ताव प्रकाशन से वापस लेने तक लागू है। अनुबंध स्वीकृति से सभी दायित्व पूरे होने तक रहता है।":"9.1. Оферта применяется с даты публикации при открытом приёме оплаты и действует до её отзыва. Договор действует с акцепта до полного исполнения обязательств.","नए मूल्य और संस्करण प्रकाशन के बाद की नई खरीद पर लागू हैं।":"Новые цены и редакции применяются к новым покупкам после их публикации.","पेज या प्रस्ताव बदलने से पहले से भुगतान की गई पहुँच का मूल्य, अवधि या दायरा नहीं बदलता।":"Изменение страницы или оферты не изменяет цену, срок и объём уже оплаченного доступа.","ऑर्डर की शर्तें सिद्ध करने के लिए प्लान और लागू प्रस्ताव संस्करण रखा जाता है।":"Для подтверждения условий заказа Исполнитель сохраняет сведения о тарифе и применённой редакции оферты.","10 सेवा प्रदाता का विवरण":"10 Реквизиты исполнителя","पूरा नाम: Anastasia Maksimovna Pokamestova":"ФИО: Покаместова Анастасия Максимовна","स्थिति: व्यक्ति, पेशेवर आय करदाता":"Статус: физическое лицо, плательщик НПД","शहर: Tver":"Город: Тверь","कानूनी रूप से महत्वपूर्ण अनुरोध नीचे दिए सेवा प्रदाता के ईमेल पर भेजें":"Юридически значимые обращения направляются на электронную почту Исполнителя, указанную ниже","फ़ोन: +7 903 033-23-19":"Телефон: +7 903 033-23-19","ईमेल: raccoon.app.labs@gmail.com":"Электронная почта: raccoon.app.labs@gmail.com","वेबसाइट: https://raccoon-app-labs.github.io/apps/hanzi-bloom/plus/":"Сайт: https://raccoon-app-labs.github.io/apps/hanzi-bloom/plus/","सेवा प्रदाता से संपर्क करें":"Связаться с исполнителем","Hanzi Plus का सार्वजनिक प्रस्ताव":"Публичная оферта Hanzi Plus","16 अक्टूबर 2026 के प्रथम संस्करण का संग्रह।":"Архив первой редакции от 16 октября 2026 года.","वर्तमान संस्करण":"Действующая редакция","Hanzi Bloom और Hanzi Keys की सुविधाओं और शिक्षण सामग्री की सशुल्क पहुँच के लिए":"О предоставлении платного доступа к функциям и учебным материалам приложений Hanzi Bloom и Hanzi Keys","दो ऐप। एक सदस्यता।":"Два приложения. Одна подписка.","Hanzi Bloom + Hanzi Keys: 299 ₽ में एक कैलेंडर महीना या 2 999 ₽ में 12 कैलेंडर महीने।":"Hanzi Bloom + Hanzi Keys: 299 ₽ за календарный месяц или 2 999 ₽ за 12 календарных месяцев.","Robokassa से एक बार भुगतान, अपने-आप नवीनीकरण नहीं।":"Разовая оплата через Робокассу, без автопродления.","सेवा छोड़ने और धनवापसी के बारे में":"Об отказе от услуги и возврате — в","16 अक्टूबर 2026 का संस्करण। शर्त संस्करण: 2026-10-16। जारी स्थान: Tver।":"Редакция от 16 октября 2026 года. Версия условий: 2026-10-16. Место составления: Тверь.","सेवा और प्लान: https://raccoon-app-labs.github.io/apps/hanzi-bloom/plus/.":"Сайт услуги и тарифов: https://raccoon-app-labs.github.io/apps/hanzi-bloom/plus/.","Hanzi Plus दो Android ऐप, Hanzi Bloom (com.enotessa.hanzi) और Hanzi Keys (com.enotessa.chinesekeys), की साझा सशुल्क निजी पहुँच है।":"Hanzi Plus — единый платный доступ для личного использования в двух Android-приложениях: Hanzi Bloom (com.enotessa.hanzi) и Hanzi Keys (com.enotessa.chinesekeys).","यह संस्करण Robokassa से रूबल में रूसी ऐप की खरीद पर लागू है।":"Настоящая редакция регулирует покупки российской версии через Робокассу в рублях.","Lava या अन्य सेवाओं से अंतरराष्ट्रीय बिक्री अभी उपलब्ध नहीं।":"Международные продажи через Lava и другие сервисы сейчас не предлагаются.","पुराने भुगतान किए ऑर्डर पर भुगतान के समय स्वीकृत शर्तें रहती हैं।":"Условия ранее оплаченных заказов сохраняются по редакции, принятой при их оплате.","सशुल्क अवधि में खाते को Bloom में प्रकाशित HSK 1–3 पाठ विज्ञापन के बिना और Keys में संरक्षित गतिविधियाँ, अभ्यास, सीखने का मार्ग और मूल घटक विश्लेषण बिना विज्ञापन मिलते हैं।":"На оплаченный срок один аккаунт получает доступ в обоих приложениях: в Hanzi Bloom — к опубликованным урокам курса HSK 1–3 без просмотра рекламы для открытия урока; в Hanzi Keys — к защищённым подпиской занятиям, практике, учебному маршруту и разбору ключей, с отключением рекламы.","दोनों ऐप में उसी ईमेल से रूसी Hanzi खाते में प्रवेश करें।":"Для доступа в каждом приложении нужно войти с одной и той же почтой в российский аккаунт Hanzi.","दूसरे ऐप के लिए अलग भुगतान नहीं चाहिए।":"Отдельно платить за второе приложение не требуется.","प्रकाशित अभ्यासों का चयन इंस्टॉल किए संस्करण पर निर्भर है।":"Состав опубликованных упражнений зависит от установленной версии.","«जल्द आ रहा है» वाले HSK 4–6 पहले से प्रकाशित सामग्री के रूप में उपलब्ध नहीं।":"HSK 4–6, отмеченные «скоро», не предлагаются как уже опубликованные материалы.","रूस के साझा Hanzi Plus प्लान: 299 रूबल में एक कैलेंडर महीना या 2 999 रूबल में 12 कैलेंडर महीने।":"Тарифы общего Hanzi Plus для России: 299 рублей за один календарный месяц либо 2 999 рублей за 12 календарных месяцев.","हर प्लान में दोनों ऐप एक साझा अवधि के लिए हैं; प्रत्येक की अलग कीमत नहीं।":"Каждый тариф включает оба приложения на один общий срок, а не отдельную оплату за каждое.","भुगतान से पहले अंतिम राशि, मुद्रा, अवधि और पहुँच का दायरा दिखता है।":"Окончательные сумма, валюта, срок и состав доступа показываются до оплаты.","मूल्य में सेवा प्रदाता की सेवा शामिल है।":"Цена включает стоимость услуги Исполнителя.","इस संस्करण में अंतरराष्ट्रीय प्लान भुगतान के लिए उपलब्ध नहीं।":"Международные тарифы в этой редакции к оплате не предлагаются.","Robokassa के सुरक्षित पेज पर गैर-नकद भुगतान होता है।":"Оплата производится безналично на защищённой платёжной странице Робокассы.","इस रिलीज़ में RuStore के रूसी ऐप से ऑर्डर बनता है।":"В текущем выпуске оформление заказа доступно из российской версии приложения в RuStore.","कार्ड और बैंक कोड भुगतान सेवा में डालें; सेवा प्रदाता संदेशों में नहीं माँगतीं।":"Данные карты и банковские коды вводятся у платёжного сервиса; Исполнитель не запрашивает их в переписке.","कार्ड की अलग मुद्रा पर रूपांतरण और बैंक खर्च बैंक तथा भुगतान सेवा तय करते हैं; पुष्टि से पहले जाँचें।":"Конвертация и возможные расходы банка при использовании иной валюты карты определяются банком и платёжным сервисом; эти условия проверяются до подтверждения платежа.","खरीद से पहले कम-से-कम एक ऐप का वर्तमान Hanzi Plus खाता वाला संस्करण इंस्टॉल करके सत्यापित ईमेल से प्रवेश करें।":"До покупки Заказчик устанавливает актуальную версию хотя бы одного приложения с экраном аккаунта Hanzi Plus и входит по подтверждённой почте.","दूसरे ऐप में वही रूसी खाता उपयोग होता है; खरीद खाते से जुड़ी है, खास इंस्टॉल या स्टोर प्रोफ़ाइल से नहीं।":"Для второго приложения используется тот же российский аккаунт: покупка связана с аккаунтом, а не с конкретной установкой или магазинным профилем.","दोनों ऐप अलग इंस्टॉल होते हैं।":"Оба приложения устанавливаются отдельно.","भुगतान, पहली सक्रियता, बहाली और सिंक के लिए इंटरनेट चाहिए।":"Для оплаты, первой активации, восстановления и синхронизации нужно подключение к Интернету.","सिस्टम आवश्यकताएँ ऐप की स्टोर सूची में हैं।":"Системные требования указываются в карточках приложений.","इंटरफ़ेस की भाषा अपने-आप खरीद का देश या खाता भंडारण क्षेत्र नहीं बदलती।":"Язык интерфейса сам по себе не меняет страну покупки или регион хранения аккаунта.","सक्रिय Plus बढ़ाने पर नई अवधि वर्तमान के बाद जुड़ती है; समाप्त हो चुका हो तो नए सक्रियण से।":"При продлении действующего Plus новый оплаченный срок добавляется после окончания текущего; после истечения — начинается с новой активации.","एक ही अवधि दोनों ऐप पर लागू होती है।":"Один срок применяется к обоим приложениям.","उसी खाते में दोबारा इंस्टॉल या दूसरे उपकरण पर बहाली का नया भुगतान या नई अवधि नहीं होती।":"Восстановление в том же аккаунте после переустановки или на другом устройстве не требует повторной оплаты и не начинает новый оплаченный срок.","पुराना रूसी Plus भी शेष अवधि के लिए दोनों ऐप में बिना अतिरिक्त शुल्क मान्य है; तय कीमत और अवधि खराब नहीं होतीं।":"Ранее купленный российский Plus также распознаётся обоими приложениями на оставшийся срок без доплаты; ранее согласованные цена и срок не ухудшаются.","समाप्ति के बाद हर ऐप के नियमों से सशुल्क सुविधाएँ बंद होती हैं, लेकिन इससे अध्ययन प्रगति नहीं मिटती।":"После окончания оплаченного срока платные возможности закрываются по правилам соответствующего приложения, но окончание подписки само по себе не удаляет учебный прогресс.","कम-से-कम एक बार उत्पादन Plus सदस्यता पाने वाले खातों में समर्थित क्लाउड प्रगति बिना नवीनीकरण रहती है।":"Для аккаунтов, хотя бы раз получивших производственную подписку Plus, облачное хранение поддерживаемого прогресса остаётся доступным без продления.","Keys केवल सीखे मूल घटकों की ID सर्वर पर रखता है; «सीखा» हटाने पर ID हटती है।":"В Hanzi Keys на сервер сохраняются только ID изученных ключей; снятие отметки «изучено» удаляет ID из списка.","Bloom समर्थित शब्द और अक्षर स्थितियाँ, पूरे पाठ, स्तर और अध्याय जाँच परिणाम रखता है।":"В Hanzi Bloom сохраняются поддерживаемые статусы слов и иероглифов, завершённые уроки, достигнутый уровень и результаты проверок глав.","यह सभी सेटिंग, पुनरावृत्ति समयसारिणी और स्थानीय फ़ाइलों की पूरी प्रति नहीं।":"Это не полная копия всех настроек, расписаний повторений и локальных файлов.","भेजने और बहाल करने के लिए समर्थित संस्करण, इंटरनेट और वही खाता चाहिए; न भेजे स्थानीय बदलाव ऐप हटाने पर खो सकते हैं।":"Для отправки и восстановления нужны поддерживающая синхронизацию версия, Интернет и вход в тот же аккаунт; неотправленные локальные изменения после удаления приложения могут быть потеряны.","अनुरोध पर खाता मिटने से क्लाउड बहाली समाप्त होती है।":"Удаление аккаунта по запросу прекращает облачное восстановление.","4.6 Hanzi Keys का मुफ़्त परिचय":"4.6 Бесплатное знакомство в Hanzi Keys","समर्थित Keys संस्करण में सर्वर द्वारा पुष्ट शुरुआत से विज्ञापन सहित 7 दिन का परिचय मिलता है।":"В поддерживающей эту модель версии Keys предоставляется 7 суток знакомства с рекламой с момента подтверждённого сервером запуска.","उसके बाद संरक्षित गतिविधियों के लिए Plus चाहिए।":"По окончании защищённые занятия требуют Plus.","मुफ़्त अवधि अपने-आप सशुल्क सदस्यता या कटौती नहीं बनाती।":"Бесплатный период сам не оформляет платную подписку и не вызывает списаний.","शुरू करने से पहले ऐप में विवरण उपलब्ध हैं।":"Подробности доступны перед началом в приложении.","पिछला संस्करण:":"Предыдущая редакция:","8 अक्टूबर 2026":"8 октября 2026 года","Hanzi Plus सदस्यता":"Подписка Hanzi Plus","ऐप देखें":"Explore app","सुविधा के लिए अनुवाद। मूल दस्तावेज़ की भाषा: {language}।":"Translation for convenience. Original document: {language}.","मूल दस्तावेज़ दिखाएँ":"Show original document","भाषा":"Language","अपनी भाषा चुनें":"Choose your language","भाषाएँ खोजें":"Search languages","भाषा सूची बंद करें":"Close language selection","भाषा {language} कर दी गई":"Language changed to {language}","पेज की भाषा भुगतान क्षेत्र या मुद्रा नहीं बदलती।":"The page language does not change your payment region or currency.","कोई भाषा नहीं मिली":"No languages found","उपकरण की भाषा उपयोग करें":"Use device language","शानदार छलाँग!":"PERFECT KICK","{v0} — {v1}. मिल गया!":"{v0} — {v1}. Found!","{v0} · {v1} सर्विंग":"{v0} · {v1} servings","{v0} — {v1} नग":"{v0} — {v1} pcs","नया कोड · {seconds} सेकंड":"Новый код · {seconds} с","· {v0} सर्विंग":"· {v0} servings","{remaining} बाकी · {done} पूरे":"{remaining} left · {done} done","समाप्त करें · {count} खरीदे":"Finish · {count} bought"});})();
